        domain = parsed.netloc
        if domain not in domains:
            domains[domain] = None
    for domain in domains:
        try:
            response = requests.get(f"http://api.ipapi.com/{domain}?access_key={API_KEY}")
            response.raise_for_status()
            data = response.json()
            domains[domain] = data
        except:
            domains[domain] = None
    return domains
